fn contains_consecutive_numbers(a: &Vec<i32>) -> bool {
    // We only need to look at adjacent pairs.
    // `windows(2)` will yield all length-2 slices of the array.
    a.windows(2)
     .any(|pair| pair[0] + 1 == pair[1])
}

